add('실습 A · Gradle','지금 필요한 의존성을 확인합니다',code("dependencies {\n    implementation 'org.springframework.boot:spring-boot-starter-webmvc'\n    implementation 'org.springframework.boot:spring-boot-starter-validation'\n}")+call('생성된 dependencies에 이미 있으면 중복 추가하지 않습니다.'),note='이 부분만 보고 생성된 테스트 의존성이나 전체 build.gradle을 덮어쓰지 않습니다. 뒤의 JUnit 테스트를 위해 Initializr가 생성한 testImplementation과 useJUnitPlatform 설정도 유지합니다.',kind='code-slide')
filepages('실습 A · 시작 클래스','ProductApplication.java','Initializr가 생성한 시작점 확인')
add('실습 A · Product','상품 객체가 지킬 규칙',table([['정보','규칙'],['id','저장소가 번호 부여'],['name','null · 공백 불가, 앞뒤 공백 제거'],['price','0 이상'],['변경 방식','생성자로 값 설정 · getter로 조회']])+call('이번 필수 실습에서는 상품 정보를 만든 뒤 수정하지 않습니다.'))
filepages('실습 A · Domain','Product.java','상품 정보와 규칙 작성')
add('실습 A · 인터페이스','저장 방법 대신 할 일을 약속합니다',linear('Service는 ProductRepository 인터페이스에 의존하며 Memory 구현체를 사용합니다',[('ProductService','역할을 사용'),('ProductRepository','저장·조회 약속'),('Memory 구현체','메모리에 보관')])+call('메서드 이름·입력·반환 타입을 인터페이스에 선언합니다.'))
filepages('실습 A · 저장소 계약','ProductRepository.java','Interface로 생성')
add('실습 A · 메모리 저장소','id를 키로 상품을 찾습니다',table([['도구','사용 목적'],['Map<Long, Product>','id와 상품 연결'],['ConcurrentHashMap','여러 요청의 기본 저장·조회에 사용'],['AtomicLong','상품 번호 증가'],['Optional<Product>','상품이 없을 수도 있음을 표현']]),note='고급 동시성 알고리즘을 가르치는 시간이 아닙니다. 빈에서 공유하는 저장 상태를 다루기 위한 도구의 역할만 설명합니다. 단일 JVM 학습용 메모리 저장소이며 재시작하면 데이터와 번호가 초기화됩니다. 여러 연산을 묶은 트랜잭션은 제공하지 않습니다.')
filepages('실습 A · 저장소 구현','MemoryProductRepository.java','Class로 생성 · implements 확인')
add('실습 A · 조회 코드 읽기','정렬해서 목록을 반환합니다',code('return store.values().stream()\n        .sorted(Comparator.comparingLong(Product::getId))\n        .toList();')+cards(('입력','저장된 상품들','Map의 values()'),('처리와 결과','id 오름차순 목록','정렬 → List로 변환')),note='교재 3장의 모던 Java 복습과 연결합니다. 메서드 참조 Product::getId는 각 상품의 id를 정렬 기준으로 읽는 표현입니다. Stream 전체 API를 설명하지 않습니다. 반환 목록은 수정용 저장소가 아니라 조회 결과입니다.',kind='code-slide')
filepages('실습 A · 없는 상품','ProductNotFoundException.java','없는 id를 나타내는 예외')
filepages('실습 A · Service','ProductService.java','생성자 주입으로 저장소 사용')
add('실습 A · 완료 기준','웹 없이 객체 연결부터 확인',steps('프로젝트를 실행해 빈 주입 오류가 없는지 확인','Service 생성자와 Repository 구현 연결 찾기','상품 규칙 위반 시 어떤 예외인지 설명','아래 Java 조립 코드가 의미하는 관계를 짝에게 설명'),note='아직 Controller를 추가하지 않았으므로 /products의 404는 정상적인 중간 상태입니다. Application main 실행으로 빈 구성이 가능한지 먼저 확인하고, 다음 테스트는 서버 없이 상품 기능을 호출합니다.')
add('실습 A · 작은 테스트','Spring 없이도 Service를 사용할 수 있습니다',code('ProductService service =\n        new ProductService(new MemoryProductRepository());\nProduct product = service.create("노트", 3000);\nProduct found = service.findById(product.getId());')+call('생성자 DI 덕분에 테스트에서도 필요한 객체를 직접 연결할 수 있습니다.'),note='이 코드는 관계를 읽는 짧은 예시이며 시작 클래스 main에 무조건 붙이라는 의미가 아닙니다. 다음 테스트 파일에서 실제로 실행합니다. plain new 객체에는 Spring AOP가 적용되지 않는다는 점을 뒤에서 연결합니다.',kind='code-slide')
filepages('실습 A · 테스트','ProductServiceTest.java','src/test/java의 같은 패키지에 생성')
add('실습 A · 테스트 실행','정상 · 잘못된 값 · 없는 상품',code('# macOS / Linux · 프로젝트 루트\n./gradlew test\n\n# Windows PowerShell\n.\\gradlew.bat test')+call('테스트 3개가 통과하면 상품 로직과 예외를 확인한 것입니다.'),note='서버와 DB를 실행하는 테스트가 아닙니다. 테스트마다 새 테스트 인스턴스와 저장소를 사용합니다. 테스트 통과는 HTTP 매핑이나 AOP 적용까지 증명하지 않습니다. Wrapper 실행 권한이 없으면 bash ./gradlew test로도 실행할 수 있습니다.',kind='code-slide')
section('03','실행 준비와 공통 처리','자동 설정 · 스타터 · AOP를 연결합니다')
add('스타터','함께 사용하는 라이브러리 묶음',cards(('Spring Web','HTTP 요청과 응답','웹 MVC와 내장 서버 구성에 필요한 의존성'),('Validation','입력값 검사','검증 API와 구현 의존성')),note='스타터는 의존성 묶음입니다. 클래스가 라이브러리에 생긴 것과 컨테이너에 빈이 등록된 것은 구분해야 합니다. 필요한 조건에 따라 자동 설정이 적용됩니다.')
add('자동 설정','조건을 보고 기본 구성을 준비합니다',linear('라이브러리와 설정 조건을 확인한 자동 설정이 필요한 기본 빈 구성을 제공합니다',[('조건 확인','라이브러리 · 설정 · 기존 빈'),('자동 설정','적합한 구성을 선택'),('실행 환경','웹 요청 처리 준비')])+call('모든 클래스가 자동 등록되거나, 모든 사용자 설정이 무조건 대체되는 것은 아닙니다.'))
add('자동 설정과 스캔','둘은 어떤 차이가 있을까요?',table([['구분','주로 하는 일'],['컴포넌트 스캔','내 코드의 @Service · @Repository 등을 찾아 등록'],['자동 설정','조건에 맞는 프레임워크 기본 구성 제공'],['스타터','관련 라이브러리 의존성을 함께 가져옴']])+call('@SpringBootApplication은 스캔과 자동 설정을 함께 시작하도록 구성됩니다.'))
add('설정 확인','기본 포트를 바꿔 봅니다',code('# src/main/resources/application.properties\nserver.port=8081')+call('저장·재시작 → 8081로 접속 → 확인 뒤 8080으로 되돌립니다.'),note='Spring Boot가 내장 서버 설정을 properties에서 읽는 예시입니다. 이 실습은 자동 설정 구현을 직접 작성하는 것이 아닙니다. 뒤의 요청 예제는 기본 8080 기준이므로 변경을 되돌려 둡니다.',kind='code-slide')
add('AOP의 출발점','모든 Service에 시간을 기록한다면',code('long started = System.nanoTime();\ntry {\n    // 원래 상품 기능 실행\n} finally {\n    // 걸린 시간 기록\n}')+call('같은 시간 기록 코드를 여러 메서드에 반복해서 넣게 됩니다.'),kind='code-slide')
add('AOP 그림','공통 처리를 프록시에서 실행합니다',proxy()+call('Service를 호출하기 전과 끝난 뒤에 공통 처리를 둘 수 있습니다.'))
add('AOP 용어','이 예제에서 세 단어만 연결',table([['용어','오늘의 코드'],['Aspect','시간 기록을 모은 TimingAspect'],['Advice','실행 전후 동작인 measure 메서드'],['Pointcut','ProductService의 어떤 메서드에 적용할지 지정']])+call('프록시는 호출을 받아 실제 객체로 전달하는 중간 객체입니다.'))
add('AOP 실습 · 의존성','Spring Boot 4.x의 스타터 추가',code("implementation 'org.springframework.boot:spring-boot-starter-aspectj'")+steps('build.gradle의 dependencies 안에 한 줄 추가','Gradle 프로젝트 새로고침','다음 TimingAspect 클래스를 같은 패키지에 작성'),note='Spring Boot 4에서 예전 spring-boot-starter-aop 이름은 spring-boot-starter-aspectj로 변경되었습니다. 이 수업에서는 Boot 자동 설정을 사용하므로 @EnableAspectJAutoProxy를 별도로 추가하지 않습니다. 공식 AOP 문서와 마이그레이션 가이드를 확인했습니다.',kind='code-slide')
filepages('AOP 실습 · 시간 기록','TimingAspect.java','서비스 호출 전후에 시간 측정')
add('AOP 실습 · 핵심 한 줄','proceed()가 원래 메서드를 실행합니다',code('try {\n    return joinPoint.proceed();\n} finally {\n    // 성공하거나 예외가 나도 시간 기록\n}')+call('proceed()를 호출하지 않으면 이 예제의 실제 상품 기능도 실행되지 않습니다.'),note='실행 시간은 짧으면 0ms가 나올 수 있습니다. 0ms 자체가 AOP 실패가 아닙니다. return 값을 전달하고 예외를 삼키지 않는 구조를 설명합니다.',kind='code-slide')
add('AOP 확인','프록시를 통과하는 호출을 비교',table([['호출 방식','이 예제의 AOP'],['Controller → 주입받은 Service','적용 대상 메서드의 시간 기록'],['테스트의 new ProductService(...)','Spring이 만든 프록시를 사용하지 않음'],['같은 객체 내부의 this.메서드()','보통 프록시를 다시 지나지 않음']]),note='Controller API가 아직 없으면 적용 확인은 뒤의 HTTP 실습에서 합니다. 이 표는 Spring의 기본 프록시 기반 AOP에 대한 설명이며 AspectJ weaving까지 일반화하지 않습니다. final/private 제약은 질문이 나오면 설명합니다.')
add('면접 연결','자동 설정과 AOP를 설명해 봅시다',steps('스타터를 추가한 것과 자동 설정은 어떻게 다른가요?','왜 Service에 직접 시간 기록 코드를 넣지 않았나요?','new로 만든 Service에도 AOP가 적용될까요?'),note='답변은 정의 암기보다 오늘의 dependencies·TimingAspect·주입 코드를 근거로 하게 합니다. DI와 AOP는 서로 다른 개념이며 DI 자체가 모든 메서드 호출을 가로채는 것은 아닙니다.')
section('04','Spring MVC와 REST API','교재 09장 · 요청이 Java 코드에 도착하는 길')
add('MVC 복습','화면의 역할과 업무의 역할을 나눕니다',table([['역할','의미'],['Model','업무 데이터와 처리 결과'],['View','사용자에게 보여줄 화면'],['Controller','입력을 받고 처리 결과를 연결']])+call('REST API도 Spring MVC를 사용하며, 응답 본문으로 데이터를 보낼 수 있습니다.'),note='Model을 특정 Entity 클래스 하나나 DB와 동일시하지 않습니다. 서버 템플릿 화면을 반환하는 Controller와 JSON을 반환하는 RestController를 구분하되 웹 MVC 기반을 공유합니다.')
add('MVC 요청 그림','DispatcherServlet이 흐름을 조율합니다',mvc(),sub='간단히 표현한 동기식 Spring MVC 요청 흐름',note='DispatcherServlet은 프런트 컨트롤러입니다. HandlerMapping으로 핸들러와 인터셉터 정보를 찾고 HandlerAdapter에 실행을 위임합니다. Service와 Repository는 Controller가 호출하는 애플리케이션 코드이며 DispatcherServlet이 모두 직접 실행하는 것은 아닙니다.')
add('MVC 응답 그림','반환 객체가 JSON 본문이 됩니다',linear('Controller의 반환값을 처리하고 메시지 변환기로 JSON을 생성해 HTTP 응답으로 보냅니다',[('Controller','응답 객체 반환'),('반환값 처리','응답 본문 방식 선택'),('메시지 변환기','객체 → JSON'),('HTTP 응답','상태 · 헤더 · 본문')])+call('@RestController에서 반환한 객체는 응답 본문으로 처리됩니다.'))
add('어노테이션 비교','@Controller와 @RestController',table([['방식','String 반환값을 읽는 기본 방식'],['@Controller','뷰 이름으로 해석하는 일반적인 MVC 방식'],['@ResponseBody를 함께 사용','응답 본문으로 전달'],['@RestController','@Controller + @ResponseBody 역할']]),note='ResponseEntity 반환처럼 명시적으로 응답을 다루는 경우도 있습니다. 무조건 모든 Controller String이 화면이라는 식으로 일반화하지 않습니다. 현재 예제의 Controller는 RestController입니다.')
add('API 설계','명사로 대상을, 메서드로 동작을',table([['설계','의미'],['POST /products','상품 컬렉션에 상품 생성'],['GET /products','상품 컬렉션 조회'],['GET /products/{id}','특정 상품 조회'],['/products/create 대신','메서드와 리소스 경로로 의도 표현']]),note='URI 모양만으로 REST의 모든 제약을 충족하는 것은 아닙니다. 오늘은 리소스·메서드·상태 코드·표현의 일관성을 연습합니다.')
add('요청 데이터','쿼리 · 경로 · 본문은 다릅니다',table([['전달 위치','Spring에서 받기'],['/products/1','@PathVariable("id")'],['/products?maxPrice=5000','@RequestParam · 추가 과제'],['POST의 JSON 본문','@RequestBody']])+call('주소창 이동은 GET입니다. POST는 API 도구나 curl로 요청합니다.'))
add('교재 09 · DTO','요청 DTO와 상품 객체를 나눕니다',linear('JSON을 요청 DTO로 읽고 Service와 Domain을 거쳐 응답 DTO로 변환합니다',[('요청 DTO','입력받을 값'),('Product','상품 정보와 규칙'),('응답 DTO','밖으로 보낼 값')])+call('DTO는 데이터를 전달하는 객체입니다. 빈으로 등록할 필요는 없습니다.'))
add('교재 09 · getter / setter','JSON 입력과 응답에서 하는 일',code('public String getName() { return name; }\npublic void setName(String name) { this.name = name; }')+cards(('요청 DTO','입력값을 담기','이번 예제는 기본 생성자와 setter 사용'),('응답 DTO','보낼 값을 읽기','이번 예제는 getter로 속성 노출')),note='JSON 변환 방법이 setter/getter만 있는 것은 아닙니다. record나 생성자 바인딩 등은 이후 확장합니다. 이번 예제는 책의 getter/setter 학습에 맞춰 Java Bean 형태를 사용합니다. 생성자를 선언하지 않은 요청 DTO에는 기본 생성자가 생깁니다.',kind='code-slide')
add('응답 설계','상태 · 헤더 · 본문을 함께 정합니다',code('HTTP/1.1 201 Created\nLocation: /products/1\nContent-Type: application/json\n\n{"id":1,"name":"노트","price":3000}')+call('생성 성공은 201, 만들어진 상품 위치는 Location으로 알립니다.'),note='이 예시는 읽기 쉽게 단순화한 HTTP 메시지입니다. 실제 헤더 값·순서는 실행 결과를 기준으로 확인합니다. 상품 id는 예시이며 실제 생성 응답의 id를 사용합니다.',kind='code-slide')
section('05','실습 B · 상품 API 완성','생성 · 목록 · 단건 조회를 연결합니다')
add('실습 B · 파일 추가','기존 프로젝트에 이어서 작성',code('src/main/java/com/example/product/\n  CreateProductRequest.java\n  ProductResponse.java\n  ProductController.java\n  ApiExceptionHandler.java')+call('검증과 오류 처리까지 포함한 최종 예제입니다. 파일 전체 코드도 확인할 수 있습니다.'),note='앞선 실습 A의 파일을 삭제하거나 새 프로젝트를 만들지 않습니다. @Valid와 DTO 제약은 다음 단계에서 의미를 풀어 설명합니다. 유효한 입력의 API를 먼저 호출하고, 오류 실습 단계에서 Handler를 완성합니다.',kind='code-slide')
add('교재 10 · 검증 미리보기','입력 규칙을 요청 DTO에 표시합니다',table([['표시','규칙'],['@NotBlank','null · 빈 문자열 · 공백만인 이름 거부'],['@NotNull','가격 필수'],['@Min(0)','가격은 0 이상'],['@Valid','Controller에서 요청 DTO 검증 실행']])+call('가격은 Integer로 받아, 빠진 값과 0원을 구분합니다.'))
filepages('실습 B · 요청 DTO','CreateProductRequest.java','이름과 가격 입력값 정의')
filepages('실습 B · 응답 DTO','ProductResponse.java','공개할 상품 정보 정의')
add('실습 B · Controller 읽기','객체 주입과 URL 매핑을 연결',code('@RestController\n@RequestMapping("/products")\npublic class ProductController {\n    private final ProductService service;\n\n    public ProductController(ProductService service) {\n        this.service = service;\n    }\n    // 다음 메서드들이 이 클래스 안에 들어갑니다.\n}')+call('아래 파일 전체 예제를 이어 작성합니다. 클래스 틀을 중복 생성하지 않습니다.'),kind='code-slide')
filepages('실습 B · 요청 연결','ProductController.java','GET과 POST 메서드 구현')
add('실습 B · 생성 메서드','요청 DTO에서 업무 처리로 전달',code('@PostMapping\npublic ResponseEntity<ProductResponse> create(\n        @Valid @RequestBody CreateProductRequest request) {\n    Product product = service.create(request.getName(), request.getPrice());\n    URI location = URI.create("/products/" + product.getId());\n    return ResponseEntity.created(location).body(new ProductResponse(product));\n}')+call('JSON 읽기 → 검증 → Service → 응답 DTO → 201'),note='전체 Controller에 이미 포함된 메서드를 읽는 페이지입니다. 같은 메서드를 한 번 더 추가하지 않습니다. 위치 헤더는 생성된 상품 id를 사용합니다. request.getPrice는 Valid 검증을 통과한 뒤 int로 전달됩니다.',kind='code-slide')
add('실습 B · 요청 도구','POST 요청을 직접 보내봅니다',steps('Postman · Bruno · 사용 가능한 API 도구 열기','POST와 http://localhost:8080/products 입력','Body를 JSON으로 설정하고 아래 값 입력','서버를 재시작한 뒤 요청하고 상태·본문·Location 확인')+code('{"name":"노트","price":3000}'),note='어떤 유료 도구 가입도 필수로 요구하지 않습니다. 이미 사용 가능한 도구를 쓰거나 다음 curl 예시로 진행합니다. 파일을 저장한 뒤 main을 재실행하고 콘솔의 시작 완료를 확인합니다.',kind='code-slide')
add('실습 B · curl 대안','프로젝트 루트에 request.json 작성',code('{"name":"노트","price":3000}')+'<div class="eyebrow">macOS / Linux</div>'+code('curl -i -H "Content-Type: application/json" --data-binary @request.json http://localhost:8080/products')+'<div class="eyebrow">Windows PowerShell</div>'+code('curl.exe -i -H "Content-Type: application/json" --data-binary "@request.json" http://localhost:8080/products'),note='한 줄 명령으로 실행합니다. request.json을 만든 폴더에서 실행하거나 실제 파일 경로로 바꿉니다. PowerShell의 curl 별칭 혼동을 피하려고 curl.exe를 명시합니다. JSON 파일에 실제 개행이나 마크다운 코드펜스는 넣지 않습니다.',kind='code-slide')
add('실습 B · 목록 확인','목록은 JSON 배열로 돌아옵니다',code('GET http://localhost:8080/products\n\n[{"id":1,"name":"노트","price":3000}]')+call('상품을 하나 더 생성하고, 서로 다른 id와 목록 개수를 확인합니다.'),note='코드 블록 첫 줄은 요청을 설명하는 표기이며 브라우저 주소창에는 URL만 입력합니다. 생성 전 빈 저장소는 200과 []를 반환합니다. id는 실제 생성 결과를 사용합니다.',kind='code-slide')
add('실습 B · 단건 확인','생성 응답의 id로 조회합니다',code('GET http://localhost:8080/products/1\n\n{"id":1,"name":"노트","price":3000}')+call('응답의 id · 이름 · 가격이 생성한 상품과 같은지 비교합니다.'),note='서버를 재시작하면 메모리 저장 상품이 사라지므로 먼저 다시 생성합니다. 모든 요청이 예시 id=1을 보장하는 것은 아닙니다. 없는 id의 404 처리는 다음 예외 핸들러 단계에서 완성합니다.',kind='code-slide')
add('AOP 결과 확인','HTTP 요청과 콘솔을 연결합니다',code('create : 0ms\nfindAll : 1ms\nfindById : 0ms')+call('상품 API를 호출할 때 Service 메서드별 시간 로그가 나오는지 확인합니다.'),note='로그의 숫자는 예시입니다. 0ms도 짧은 실행에서 정상적으로 나올 수 있습니다. 로그가 없다면 Aspect의 Component, 패키지, 스타터, Pointcut, 서버 재실행과 Controller가 주입받은 Service를 사용하는지 확인합니다.',kind='code-slide')
section('06','실습 C · 검증과 예외 응답','교재 10장 · 실패한 요청도 설계합니다')
add('검증의 두 위치','입력 형식과 업무 규칙을 지킵니다',cards(('요청 DTO','들어오는 입력 검사','필수 값 · 공백 · 가격 범위'),('Domain','객체의 규칙 보장','다른 경로로 생성해도 유효한 상품'))+call('HTTP 입력을 거치지 않는 코드도 있으므로 Domain의 규칙도 유지합니다.'))
add('검증 요청 흐름','잘못된 DTO는 Service 호출 전에 멈춥니다',linear('요청 본문 변환 후 DTO 검증에 실패하면 Controller 메서드를 실행하지 않고 예외 처리로 이어집니다',[('JSON 읽기','요청 DTO 생성'),('@Valid 검증','입력 규칙 확인'),('통과한 경우','Controller · Service')])+call('검증 실패 → 예외 처리 → 400 응답'),note='이 예제는 Valid RequestBody 객체 검증이므로 MethodArgumentNotValidException을 처리합니다. JSON 파싱이나 타입 변환 실패는 HttpMessageNotReadableException으로 별도 처리합니다. 메서드 검증 전체를 일반화하지 않습니다.')
add('없는 상품','업무 예외를 HTTP 응답으로 바꿉니다',linear('Repository의 빈 Optional이 Service에서 예외가 되고 전역 핸들러가 404 응답으로 변환합니다',[('Repository','상품 없음 · Optional.empty'),('Service','ProductNotFoundException'),('예외 핸들러','404 + JSON 본문')])+call('예외 핸들러를 작성하기 전과 후의 응답을 비교합니다.'))
add('전역 예외 처리','여러 Controller의 오류 응답을 모읍니다',table([['예외','응답'],['ProductNotFoundException','404 · 상품을 찾을 수 없음'],['MethodArgumentNotValidException','400 · 입력 규칙 위반'],['HttpMessageNotReadableException','400 · JSON 문법이나 타입 오류'],['IllegalArgumentException','400 · 이 예제의 Domain 규칙 위반']]),note='모든 시스템에서 IllegalArgumentException을 400으로 취급해야 한다는 뜻이 아닙니다. 여기서는 직접 정의한 상품 규칙 위반에 사용하므로 범위를 제한합니다. 예상하지 못한 모든 Exception을 잡아 200으로 돌려주지 않습니다.')
filepages('실습 C · 오류 응답','ApiExceptionHandler.java','기존 프로젝트의 같은 패키지에 생성')
add('실습 C · 실패 사례','가격이 잘못되거나 빠진 요청',code('{"name":"노트","price":-1}\n\n{"name":"노트"}\n\n{"name":"노트","price":"무료"}')+call('세 요청 모두 400 · 저장된 상품 수는 늘어나지 않아야 합니다.'),note='각 JSON 객체를 별도 요청으로 보냅니다. 세 객체를 한 본문에 붙이지 않습니다. 첫 번째와 두 번째는 DTO 검증, 세 번째는 JSON 값의 타입 변환 문제입니다. 요청별 전후 목록 개수를 비교합니다.',kind='code-slide')
add('실습 C · 이름 검사','공백 이름과 정상 이름을 비교',code('{"name":"   ","price":3000}\n\n{"name":"  노트  ","price":3000}')+call('공백만인 이름은 400 · 정상 이름의 앞뒤 공백은 Domain에서 제거합니다.'),note='두 JSON 객체를 각각 별도 요청합니다. NotBlank는 검사하며 문자열을 정리하는 기능은 아닙니다. 실제 strip은 Product 생성자에서 수행합니다. 정상 요청은 201이며 응답 name은 노트입니다.',kind='code-slide')
add('실습 C · 404 응답','없는 상품의 오류 본문 확인',code('GET http://localhost:8080/products/999999\n\nHTTP/1.1 404 Not Found\nContent-Type: application/json\n\n{"message":"상품을 찾을 수 없습니다: 999999"}')+call('빈 목록 []와 없는 단건의 404는 서로 다른 결과입니다.'),note='실제 저장된 id가 아닌 값을 선택합니다. 프로젝트에 다른 예외 핸들러를 중복 작성하지 않도록 합니다. ResponseEntity.status(...).body(...)가 상태와 본문을 설정하는 지점을 찾아 설명합니다.',kind='code-slide')
add('실습 C · 확인표','실행 결과로 완료 여부를 판단',table([['요청','기대 결과'],['상품 생성 / 목록 / 단건','201 / 200 / 200'],['빈 저장소의 목록','200 + []'],['공백 이름 · 음수 가격 · 빠진 가격','400 + 오류 본문'],['없는 상품 id','404 + 오류 본문']]))
add('문제 해결','오류가 난 위치부터 구분합니다',table([['증상','먼저 확인'],['서버 시작 실패','빈 후보 · 패키지 · Gradle 동기화'],['정상 POST도 400','Content-Type · JSON 키 · 값의 타입'],['없는 상품이 500','예외 핸들러 등록과 예외 타입'],['생성한 상품이 사라짐','서버 재시작 · 메모리 저장 방식'],['시간 로그가 없음','Aspect · Pointcut · 주입받은 Service']]))
section('07','검증하고 설명하기','교재 12장 · 코드와 실행 결과로 공유합니다')
add('테스트의 범위','단위 테스트와 API 확인은 다릅니다',table([['확인 방법','무엇을 알 수 있나요?'],['ProductServiceTest','객체 연결 후 상품 처리와 예외'],['API 요청 도구','URL · JSON 변환 · 검증 · HTTP 상태'],['콘솔 로그','프록시를 통한 AOP 실행 여부']])+call('단위 테스트 통과만으로 API 전체가 완성됐다고 판단하지 않습니다.'))
add('교재 12 · 모킹 연결','테스트용 객체로 바꿀 수도 있습니다',code('ProductRepository repository = new MemoryProductRepository();\nProductService service = new ProductService(repository);')+call('오늘은 실제 메모리 구현체를 사용합니다. Mock 도구 사용은 다음에 확장합니다.'),note='Memory 저장소 자체는 동작하는 구현체입니다. 이 코드를 Mockito mock이라고 설명하지 않습니다. 인터페이스와 생성자 DI 덕분에 이후 fake 또는 mock으로 바꿀 수 있다는 연결까지만 합니다.',kind='code-slide')
add('발표 준비','별도 PPT 없이 화면으로 보여줍니다',steps('정상 상품 생성 → 목록 → 단건 조회','잘못된 입력의 400과 없는 상품의 404','Controller → Service → Repository 코드 연결','AOP 로그와 오늘 해결한 오류 하나 설명'),note='실습과 발표를 합쳐 순수 학습시간 약 180분을 확보합니다. 팀 수에 맞춰 팀별 발표 시간을 조절하고 모든 팀이 최소 하나의 실행 결과와 코드 관계를 설명하게 합니다. 개인정보나 비밀키가 화면에 없도록 일반 학습 자료를 사용합니다.')
add('발표 질문','동작과 이유를 함께 설명해 봅시다',steps('누가 ProductService 객체를 만들고 연결했나요?','Service가 인터페이스를 받는 이유는 무엇인가요?','잘못된 요청은 어디에서 400으로 바뀌나요?','서버를 껐다 켜면 상품은 어떻게 될까요?'))
add('빠른 팀 · 추가 과제 ①','가격 조건으로 목록 조회',code('GET /products?maxPrice=5000')+steps('maxPrice가 없으면 전체 목록 반환','있으면 해당 가격 이하 상품만 반환','음수 조건은 400 · 결과가 없으면 []'),note='Controller에서 Optional이나 required=false로 입력을 받고 Service에 조건을 전달하는 방식으로 확장합니다. Repository의 기존 저장 데이터를 변경하지 않습니다. 단건 경로와 충돌하지 않도록 목록 메서드 하나를 수정합니다.',kind='code-slide')
add('빠른 팀 · 추가 과제 ②','수정과 삭제까지 확장',table([['요청','완료 기준'],['PUT /products/{id}','이름·가격 전체 변경 · id 유지'],['DELETE /products/{id}','삭제 성공 204 · 응답 본문 없음'],['없는 id / 잘못된 입력','404 / 400 유지']])+call('필수 API와 발표 준비를 마친 팀만 선택합니다.'),note='Repository 계약부터 필요한 동작을 추가하고 Service·Controller까지 연결합니다. PUT의 없는 자원 정책은 이 과제에서 404로 정한 것입니다. 새 상품 저장 메서드로 수정하면 id가 바뀔 수 있으므로 기존 id를 유지하는 방법을 설계합니다. 원자적인 변경이나 경쟁 요청까지 완성하는 것은 이번 요구 범위가 아닙니다.')
add('책 11장으로 연결','다음에는 저장소를 바꿉니다',linear('ProductService는 Repository 역할을 유지하고 저장 구현을 메모리에서 데이터베이스로 확장할 수 있습니다',[('현재 Service','업무 흐름 유지'),('Repository 역할','저장·조회 약속'),('다음 구현','DB 연동')])+call('오늘은 DB 설치 없이 객체 연결과 HTTP 흐름을 먼저 이해합니다.'),note='DB 전환 시 트랜잭션·식별자 생성·조회 방식 등 구현과 계약 조정이 필요할 수 있습니다. 아무 코드도 바꾸지 않고 DB가 저절로 붙는다고 설명하지 않습니다. 책 13·14장은 종합 과제로 연결합니다.')
add('정리','요청 하나로 오늘 배운 것을 연결',linear('HTTP 요청이 Controller와 DI로 연결된 Service를 호출하고 Repository의 상품 데이터를 사용합니다',[('HTTP 요청','메서드 · 경로 · JSON'),('Controller','검증 · 응답 연결'),('Service','업무 흐름 · AOP'),('Repository','상품 저장·조회')])+call('컨테이너는 객체를 연결하고, MVC는 요청을 연결합니다.'))
refs=[('교재 · CH 09 / 10 / 12','https://www.yes24.com/product/goods/124434554','읽기 범위와 개념 연결'),('DI · 빈 등록','https://docs.spring.io/spring-framework/reference/core/beans/dependencies/factory-collaborators.html','생성자 주입'),('빈 스코프','https://docs.spring.io/spring-framework/reference/core/beans/factory-scopes.html','기본 싱글턴'),('자동 설정','https://docs.spring.io/spring-boot/reference/using/auto-configuration.html','조건과 기본 구성'),('Spring AOP','https://docs.spring.io/spring-framework/reference/core/aop/proxying.html','프록시와 호출'),('Spring MVC · 검증','https://docs.spring.io/spring-framework/reference/web/webmvc/mvc-controller/ann-validation.html','요청 DTO 검증')]
add('참고','교재와 공식 문서','<div class="references">'+''.join(f'<a href="{u}" target="_blank" rel="noopener"><b>{n} ↗</b><span>{d}</span></a>' for n,u,d in refs)+'</div>')
# Emit a self-contained, read-only deck. No private notes or local editing drafts are shipped.
css=(R/'theme.css').read_text();slides=[]
for i,d in enumerate(S):
 src='' if not d['source'] else '<button class="source-button" data-source-key="'+esc(d['source'])+'">파일 전체 코드 ↗</button>'
 slides.append('<section class="slide '+d['kind']+(' active' if i==0 else '')+'" data-index="'+str(i)+'" data-slide-id="lesson3-'+str(i)+'" aria-label="'+esc(re.sub('<[^>]*>',' ',d['title']))+'" aria-hidden="'+('false' if i==0 else 'true')+'"><div class="topline"><span class="brand">SPRING BOOT &amp; AI</span><span class="chapter-tag">'+esc(d['ch'])+'</span></div><h1>'+d['title']+'</h1>'+src+('<div class="subtitle">'+d['sub']+'</div>' if d['sub'] else '')+'<div class="content">'+d['body']+'</div><footer class="foot"><span>2026.11.07</span><span>'+f'{i+1:02} / {len(S):02}'+'</span></footer></section>')
meta=[{k:d[k] for k in ('ch','title')} for d in S]
out='<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="교재 9·10·12장과 함께 배우는 IoC·DI·AOP·Spring MVC·상품 API 실습"><title>11월 7일 · 객체 연결과 상품 API</title><style>'+css+'</style></head><body data-deck-revision="2026-11-07-v1"><main id="workspace" aria-label="강의 슬라이드"><div id="stage">'+''.join(slides)+(R/'controls.html').read_text()+'<script type="application/json" id="deck-data">'+json.dumps(meta,ensure_ascii=False).replace('<','\\u003c')+'</script><script type="application/json" id="source-data">'+json.dumps(SOURCES,ensure_ascii=False).replace('<','\\u003c')+'</script><script>'+(R/'engine.js').read_text()+'</script></body></html>'
assert not any(t in out for t in ['강사 시연','contenteditable=','localStorage'])
assert not re.search('gray',''.join(slides),re.I)
(R/'index.html').write_text(out)
(R/'slide-index.json').write_text(json.dumps([{'n':i+1,'title':d['title'],'chapter':d['ch'],'source':d['source']} for i,d in enumerate(S)],ensure_ascii=False,indent=2))
# Full source examples are canonical for verification, but are not a downloadable starter project.
(R/'metadata-private.json').write_text(json.dumps(S,ensure_ascii=False,indent=2))
print('Created',len(S),'slides;',sum(d['source'] is not None for d in S),'file-code pages;',out.count('class="diagram"'),'SVG diagrams;',len(out.encode()),'bytes')
